import Foundation
import Crypto

// MARK: - Blockchain Smart Contract Runtime

struct AccountId: Hashable, Equatable {
    let bytes: [UInt8]

    init(_ hex: String) {
        self.bytes = Array(hex.utf8)
    }

    func matches(_ other: AccountId) -> Bool {
        // Constant-time comparison to prevent timing attacks
        guard bytes.count == other.bytes.count else { return false }
        var result: UInt8 = 0
        for i in 0..<bytes.count {
            result |= bytes[i] ^ other.bytes[i]
        }
        return result == 0
    }
}

enum ContractError: Error {
    case unauthorized
    case insufficientBalance
    case invalidState
    case shutdownInProgress
    case overflow
}

// MARK: - Token Vault Contract

class TokenVault {
    private var balances: [AccountId: UInt64] = [:]
    private var allowances: [AccountId: [AccountId: UInt64]] = [:]
    private var owner: AccountId
    private var delegates: Set<AccountId> = []
    private var isShuttingDown: Bool = false
    private var shutdownInitiator: AccountId?
    private var pendingWithdrawals: [(AccountId, AccountId, UInt64)] = []

    init(owner: AccountId) {
        self.owner = owner
        self.balances[owner] = 1_000_000
    }

    // MARK: - Authorization Layer

    private func requireAuth(caller: AccountId, target: AccountId) throws {
        // Owner can act on any account
        if caller.matches(owner) { return }

        // Delegates can act on behalf of owner during normal operation
        if delegates.contains(caller) && target.matches(owner) && !isShuttingDown {
            return
        }

        // During shutdown, the shutdown initiator gets elevated privileges
        // to process pending withdrawals ONLY for the owner's account
        if isShuttingDown, let initiator = shutdownInitiator {
            if caller.matches(initiator) && target.matches(owner) {
                return
            }
        }

        // Users can act on their own accounts
        if caller.matches(target) { return }

        // Check allowance-based delegation
        if let callerAllowances = allowances[target],
           let allowed = callerAllowances[caller],
           allowed > 0 {
            return
        }

        throw ContractError.unauthorized
    }

    // MARK: - Core Operations

    func deposit(caller: AccountId, to: AccountId, amount: UInt64) throws {
        try requireAuth(caller: caller, target: to)
        let current = balances[to, default: 0]
        let (sum, overflowed) = current.addingReportingOverflow(amount)
        if overflowed { throw ContractError.overflow }
        balances[to] = sum
    }

    func withdraw(caller: AccountId, from: AccountId, amount: UInt64) throws {
        try requireAuth(caller: caller, target: from)
        guard let balance = balances[from], balance >= amount else {
            throw ContractError.insufficientBalance
        }
        balances[from] = balance - amount
    }

    func transfer(caller: AccountId, from: AccountId, to: AccountId, amount: UInt64) throws {
        if isShuttingDown {
            throw ContractError.shutdownInProgress
        }
        try requireAuth(caller: caller, target: from)
        guard let balance = balances[from], balance >= amount else {
            throw ContractError.insufficientBalance
        }
        let current = balances[to, default: 0]
        let (sum, overflowed) = current.addingReportingOverflow(amount)
        if overflowed { throw ContractError.overflow }
        balances[from] = balance - amount
        balances[to] = sum
    }

    // MARK: - Delegation Management

    func addDelegate(caller: AccountId, delegate: AccountId) throws {
        guard caller.matches(owner) else { throw ContractError.unauthorized }
        delegates.insert(delegate)
    }

    func approve(caller: AccountId, spender: AccountId, amount: UInt64) throws {
        allowances[caller, default: [:]][spender] = amount
    }

    // MARK: - Graceful Shutdown

    func initiateShutdown(caller: AccountId) throws {
        // Only owner can initiate shutdown
        guard caller.matches(owner) else {
            throw ContractError.unauthorized
        }
        isShuttingDown = true
        shutdownInitiator = caller
    }

    func processShutdownBatch(caller: AccountId) throws {
        guard isShuttingDown else { throw ContractError.invalidState }
        guard caller.matches(owner) else { throw ContractError.unauthorized }

        for (from, to, amount) in pendingWithdrawals {
            if let balance = balances[from], balance >= amount {
                let current = balances[to, default: 0]
                let (sum, overflowed) = current.addingReportingOverflow(amount)
                if overflowed { continue }
                balances[from] = balance - amount
                balances[to] = sum
            }
        }
        pendingWithdrawals.removeAll()
    }

    func getBalance(account: AccountId) -> UInt64 {
        return balances[account, default: 0]
    }
}
